      console.log(
        "✅ Online profile refreshed:",
        fixedProfile.cleanName || fixedProfile.rawName || phone
      );
    })
    // ==========================================================
    // 📴 UNEXPECTED NETWORK / RUNTIME FAILURE
    //
    // NEVER revoke the session here.
    // ==========================================================
    .catch(function(err) {
      console.warn("⚠ refreshOnlineProfile network/runtime failure:", err);

      if (typeof updateNetworkStatus === "function") {
        updateNetworkStatus("offline");
      }
    });
  } catch (err) {
    // ==========================================================
    // 🛡 OUTER SAFETY
    //
    // Even an unexpected local JavaScript error must NOT
